main.py <pre><code>"""Evolve a SQL schema migration: an artifact domain registered from user code.

Nothing below is built into the library. ``Migration`` is an ordinary tuple
subclass, ``MigrationCodec`` is an ordinary object, and one
``register_artifact_type`` call is the whole integration — the coordinator has
no branch for it. The evaluator applies the candidate to a throwaway in-memory
SQLite database and scores the schema it actually builds, so "does this
migration work" is answered by running it rather than by reading it.

Fully deterministic: no model provider and no credential. The search itself is
in-memory; only the closing durable-local demonstration touches disk, inside a
temporary directory it deletes.
"""

from __future__ import annotations

import sqlite3
from collections.abc import Iterable
from tempfile import TemporaryDirectory
from typing import ClassVar

import meta_evolve as meta
from meta_evolve.domain import InvalidOutput


TARGET_SCHEMA = {
    "users": {"id": "INTEGER PRIMARY KEY", "email": "TEXT"},
    "orders": {"id": "INTEGER PRIMARY KEY", "user_id": "INTEGER", "total": "REAL"},
}


# --- 1. the value type ------------------------------------------------------


class Migration(tuple):
    """An ordered sequence of SQL statements, one statement per element.

    The constructor owns what makes a value *a migration*: statements are
    non-blank text and carry no terminator, so one element is one statement.
    Whether the SQL runs, and whether it builds the right schema, is the
    evaluator's question and is answered by executing it.
    """

    KIND: ClassVar[str] = "sql-migration"
    REPRESENTATION: ClassVar[str] = "statement-list-v1"

    __slots__ = ()

    def __new__(cls, statements: Iterable[object] | str = ()) -&gt; "Migration":
        if isinstance(statements, str):
            # Without this, tuple() would silently split one statement into
            # a migration of single characters.
            raise TypeError("a migration is a sequence of statements, not one string")
        statements = tuple(statements)
        for statement in statements:
            if not isinstance(statement, str) or not statement.strip():
                raise ValueError("every migration statement must be non-blank text")
            if ";" in statement:
                raise ValueError(
                    "one statement per element, written without a terminator"
                )
        return super().__new__(cls, statements)


SEED = Migration(("CREATE TABLE users (id INTEGER PRIMARY KEY)",))


# --- 2. the codec -----------------------------------------------------------


class MigrationCodec:
    """Translates ``Migration`` values to and from their durable payload.

    The payload is the flat tuple of statement strings — the statements are
    the whole artifact, and a tuple of strings is already a frozen value, so
    what ``encode`` returns is exactly what a committed payload holds and
    ``decode(encode(v))`` is ``v`` with no normalization step.
    """

    kind = Migration.KIND
    representation = Migration.REPRESENTATION
    interfaces = ("ordered-statements/v1",)

    def encode(self, value: object) -&gt; tuple[str, ...]:
        if not isinstance(value, Migration):
            raise TypeError("sql-migration tasks require a Migration value")
        return tuple(value)

    def decode(self, payload: object) -&gt; Migration:
        return Migration(payload)


# --- 3. proposer and evaluator, both plain callables ------------------------


def apply_migration(migration: Migration) -&gt; dict[str, tuple[str, ...]]:
    """Run the migration in a throwaway database and read the schema back."""

    connection = sqlite3.connect(":memory:")
    try:
        for statement in migration:
            connection.execute(statement)
        tables = [
            name
            for (name,) in connection.execute(
                "SELECT name FROM sqlite_master WHERE type = 'table' ORDER BY name"
            )
        ]
        return {
            table: tuple(
                row[1]
                for row in connection.execute(f'PRAGMA table_info("{table}")')
            )
            for table in tables
        }
    finally:
        connection.close()


def extend(parent: Migration, context: object) -&gt; Migration:
    """Append the one statement that closes the next gap against the target."""

    schema = apply_migration(parent)
    for table, columns in TARGET_SCHEMA.items():
        if table not in schema:
            column, declaration = next(iter(columns.items()))
            return Migration(
                (*parent, f"CREATE TABLE {table} ({column} {declaration})")
            )
        for column, declaration in columns.items():
            if column not in schema[table]:
                return Migration(
                    (*parent, f"ALTER TABLE {table} ADD COLUMN {column} {declaration}")
                )
    # Unreached in the pinned run: `satisfy` stops the search the moment the
    # schema matches. It keeps `extend` total for readers who raise the budget.
    return parent


def score(candidate: Migration) -&gt; dict[str, float] | InvalidOutput:
    """Fraction of the target's columns the migration actually builds."""

    try:
        built = apply_migration(candidate)
    except sqlite3.Error as error:
        # The candidate's SQL is at fault, not the evaluator: a migration
        # SQLite refuses is invalid output, not a migration that scores zero.
        return InvalidOutput(
            message=str(error), details={"sqlite_error": type(error).__name__}
        )
    wanted = {
        (table, column)
        for table, columns in TARGET_SCHEMA.items()
        for column in columns
    }
    present = {
        (table, column) for table, columns in built.items() for column in columns
    }
    return {"schema_match": len(wanted &amp; present) / len(wanted)}


# --- 4. register the domain and run -----------------------------------------

registry = meta.Registry()
registry.register_artifact_type(MigrationCodec())

experiment = meta.Experiment(
    task=meta.Task(
        evaluator=score,
        artifact=Migration,
        objectives=(meta.Maximize("schema_match", satisfy=1.0),),
        budget=meta.Budget(evaluations=6, trials=5),
    ),
    seed=SEED,
    proposer=extend,
    search=meta.Greedy(max_trials=5),
    registry=registry,
)
result = meta.run(experiment)

best = result.best()
print("domain:", best.kind, best.representation)
print("interfaces:", registry.artifact_interfaces(best.kind, best.representation))
for statement in best.value:
    print(statement)
print("schema:", apply_migration(best.value))
print("schema_match:", [trial.metrics["schema_match"] for trial in result.lineage()])


# --- 5. what a registered domain does not get yet ---------------------------
#
# Durable runs need a manifest that says which code rebuilds a payload. A
# registered codec is a live object, so `mode="durable-local"` fails closed
# rather than promising a resume it cannot verify. Run the refusal instead of
# claiming it.

registered_evaluator = registry.register_evaluator(
    "sql-migrations:score", "1", score, deterministic=True, retry_safe=True
)
registered_proposer = registry.register_proposer(
    "sql-migrations:extend", "1", extend, deterministic=True, retry_safe=True
)
durable_task = meta.Task(
    evaluator=registered_evaluator,
    artifact=Migration,
    objectives=(meta.Maximize("schema_match", satisfy=1.0),),
    budget=meta.Budget(evaluations=2, trials=1),
)
with TemporaryDirectory() as directory:
    with meta.Storage.durable(directory) as storage:
        try:
            experiment = meta.Experiment(
                task=durable_task,
                seed=SEED,
                proposer=registered_proposer,
                search=meta.Greedy(max_trials=1),
                registry=registry,
            )
            meta.run(experiment, storage=storage, mode="durable-local")
        except meta.CapabilityError as refusal:
            print("durable-local refuses it:", refusal)
        else:
            raise AssertionError("durable-local must refuse a registered codec")
